    {
      "chord_quality": "dom7",
      "function_role": "upper-extension-voicing-symbol-order",
      "narrative": "Pass specifies that chord-symbol qualifier order equals voice order bottom-to-top. Ch.2 p.20: 'These chord symbols are written so that the order of appearance of notes coincides with the spelling of the chord symbol. For example, D7+9+5 means D7 with the raised 9th next, and the raised 5th on top.' The altered dominant D7+9+5 exemplifies the convention.",
      "source_principle_ids": [],
      "source_work_id": "guitar-chords",
      "references": [
