    },
    {
      "chord_quality": "dom7alt",
      "function_role": "tritone-substitution-for-dominant",
      "narrative": "The tritone substitute Db7+9b5 is presented as interchangeable with G13b5. Ch.2 p.15: 'The fifth chord is G13b5 (or Db7+9b5) which resolves into Cma9.' The parenthetical equivalence signals the substitution as a practical re-spelling, not a separate color.",
      "source_principle_ids": [],
      "source_work_id": "guitar-chords",
      "references": [
