    },
    {
      "chord_quality": "dom7alt",
      "function_role": "altered-upper-structure-bottom-to-top-order",
      "narrative": "The altered dominant D7+9+5 demonstrates the voicing-layer convention. Ch.2 p.20: 'D7+9+5 means D7 with the raised 9th next, and the raised 5th on top.' Each suffix maps directly to a voice layer ascending from the seventh-chord shell.",
      "source_principle_ids": [],
