    },
    {
      "chord_quality": "dim7",
      "function_role": "interchangeable-approach-chord-multiple-resolutions",
      "narrative": "Pass treats diminished chords as freely interchangeable approach chords that can resolve to multiple targets. Ch.2 p.15: 'Resolve the last chord in this sequence into any chord. For example: (1) Dm7 \u2014 G7 \u2014 Cma7, or (2) Em7 \u2014 Eb9 \u2014 Dm9 \u2014 Db9.' The open-resolution prescription underscores diminished's non-committed approach function.",
      "source_principle_ids": [],
