    },
    {
      "chord_quality": "dim7",
      "function_role": "substitute-for-dominant-seventh-flat-nine",
      "narrative": "Pass explicitly substitutes diminished chords for 7b9 harmony in a minor-key context. Ch.2 p.15: 'Use of diminished chords for seventh flat ninth chord movement, utilizing the basic pattern of A7 \u2014 Dm \u2014 G7 \u2014 C.' The diminished voicing replaces the A7b9 functional slot while retaining the approach-tone content.",
      "source_principle_ids": [],
