    },
    {
      "chord_quality": "aug7",
      "function_role": "sustained-color-before-cycle-resolution",
      "narrative": "Augmented chords are held as a sustained color before resolving chromatically into a cycle. Ch.2 p.15: 'The first six chords are basically G aug. Movement is used chromatically to get to the basic cycle (A7 \u2014 D7 \u2014 G).' The prescription is to sustain the augmented sound across multiple voicings rather than move through it quickly.",
      "source_principle_ids": [],
