    },
    {
      "chord_quality": "aug7",
      "function_role": "resolution-target-from-half-diminished",
      "narrative": "G aug serves as the final resolution target in the half-diminished-to-augmented passage. Ch.2 p.15: 'A7b9 to Dm7b5 resolving finally to G aug.' The augmented chord receives the cadence rather than a tonic major, functioning as an open, unresolved color endpoint.",
      "source_principle_ids": [],
